export const ZC_MARKETS: readonly ZcMarket[] = ["ERG", "SigUSD"] as const;

export function marketTokenId(market: ZcMarket): string | null {
  return market === "SigUSD" ? ZC_SIGUSD_TOKEN_ID : null;
}

export function marketByTokenId(tokenId: string | null): ZcMarket | null {
  if (tokenId === null) return "ERG";
  if (tokenId.toLowerCase() === ZC_SIGUSD_TOKEN_ID) return "SigUSD";
  return null;
}

export function marketNamed(name: string): ZcMarket | null {
  const clean = name.trim().toLowerCase();
  if (clean === "erg") return "ERG";
  if (clean === "sigusd") return "SigUSD";
  return null;
}

export type ZcKind =
  | "BondVault"
  | "FractionalVault"
  | "FractionalMint"
  | "DutchAuctionVault"
  | "WrapVault"
  | "WrapMint"
  | "Bond"
  | "Order"
  | "LendOffer"
  | "SaleOrder"
  | "PricedAsk"
  | "DutchAuctionMint"
  | "PricedOrder"
  | "LotAuction";

export type ZcExpression =
  | "MaturityLiquidation"
  | "OracleLiquidation"
  | "CollateralPolicy"
  | "FillGuard"
  | "YieldOrderPricing"
  | "YieldAskPricing"
  | "GuardedYieldPricing"
  | "CurveOrderPricing";

export interface ZcScript {
  readonly kind: ZcKind;
  readonly market: ZcMarket | null;
  readonly ergoTreeHex: string;
  readonly treeHash: string;
  readonly templateHash: string;
  readonly label: string;
}

export interface ZcExpressionEntry {
  readonly expression: ZcExpression;
  readonly market: ZcMarket | null;
  readonly hash: string;
}

