const SCRIPT_BY_TREE = new Map<string, ZcScript>(
  ZC_SCRIPTS.map((s) => [s.ergoTreeHex, s])
);

const SCRIPT_BY_KEY = new Map<string, ZcScript>(
  ZC_SCRIPTS.map((s) => [`${s.kind}:${s.market ?? "-"}`, s])
);

const EXPR_BY_KEY = new Map<string, string>(
  ZC_EXPRESSIONS.map((e) => [`${e.expression}:${e.market ?? "-"}`, e.hash])
);

const ADDRESS_CACHE = new Map<string, string>();

export const ALL_ZC_BOX_TREES: readonly string[] = ZC_SCRIPTS.map((s) => s.ergoTreeHex);

export function classifyErgoTree(ergoTreeHex: string): ZcScript | null {
  return SCRIPT_BY_TREE.get(ergoTreeHex.toLowerCase()) ?? null;
}

export function getZcScript(kind: ZcKind, market: ZcMarket | null): ZcScript {
  const found = SCRIPT_BY_KEY.get(`${kind}:${market ?? "-"}`);
  if (!found) {
    throw new Error(`Unknown ZC script ${kind} for market ${market ?? "shared"}`);
  }
  return found;
}

export function getZcExpressionHash(expression: ZcExpression, market: ZcMarket | null): string {
  const m = expression === "MaturityLiquidation" ? null : market;
  const found = EXPR_BY_KEY.get(`${expression}:${m ?? "-"}`);
  if (!found) {
    throw new Error(`Unknown ZC expression ${expression} for market ${m ?? "shared"}`);
  }
  return found;
}

export function getZcScriptAddress(script: ZcScript, network: Network = Network.Mainnet): string {
  const cacheKey = `${network}:${script.treeHash}`;
  const hit = ADDRESS_CACHE.get(cacheKey);
  if (hit) return hit;
  const addr = ErgoAddress.fromErgoTree(script.ergoTreeHex, network).encode(network);
  ADDRESS_CACHE.set(cacheKey, addr);
  return addr;
}
